var{contextBridge:n,ipcRenderer:a}=require("electron");n.exposeInMainWorld("api",{hashSha256:e=>a.invoke("hash-sha256",e),readFile:e=>a.invoke("read-file",e),saveFile:(e,t)=>a.invoke("save-file",{filePath:e,content:t}),checkForUpdates:()=>a.invoke("check-for-updates"),installUpdateNow:()=>a.invoke("install-update-now"),onOpenFile:e=>{a.on("open-md-file",(t,o)=>{try{e&&e(o)}catch{}})},onUpdateAvailable:e=>{a.on("update-available",(t,o)=>{try{e&&e(o)}catch{}})},onUpdateProgress:e=>{a.on("update-download-progress",(t,o)=>{try{e&&e(o)}catch{}})},onUpdateDownloaded:e=>{a.on("update-downloaded",(t,o)=>{try{e&&e(o)}catch{}})},onUpdateError:e=>{a.on("update-error",(t,o)=>{try{e&&e(o)}catch{}})}});
